# codegen.py
class CodeGenerator:
    def generate_code(self, tac_list) -> str:
        python_lines = [
            "# Generated by Aura Compiler Studio",
            "def main():"
        ]

        # First pass to identify labels
        labels = set(tac.result for tac in tac_list if tac.op == 'LABEL')
        
        # Translate TAC into Python statements
        for tac in tac_list:
            if tac.op == 'LABEL':
                python_lines.append(f"    # Label {tac.result}")
            elif tac.op == '=':
                python_lines.append(f"    {tac.result} = {tac.arg1}")
            elif tac.op in ('+', '-', '*', '/', '==', '!=', '<', '>', '<=', '>='):
                python_lines.append(f"    {tac.result} = {tac.arg1} {tac.op} {tac.arg2}")
            elif tac.op == 'PRINT':
                python_lines.append(f"    print({tac.arg1})")
            elif tac.op == 'JUMP_IF_FALSE':
                python_lines.append(f"    # Branch if not {tac.arg1} -> {tac.result}")
            elif tac.op == 'GOTO':
                python_lines.append(f"    # Jump -> {tac.result}")

        # Control flow executor engine for Python target
        python_lines = [
            "# Generated by Aura Compiler Studio",
            "def main():"
        ]

        # Emit standard Python translation
        indent = "    "
        for tac in tac_list:
            if tac.op == '=':
                python_lines.append(f"{indent}{tac.result} = {tac.arg1}")
            elif tac.op in ('+', '-', '*', '/', '==', '!=', '<', '>', '<=', '>='):
                python_lines.append(f"{indent}{tac.result} = {tac.arg1} {tac.op} {tac.arg2}")
            elif tac.op == 'PRINT':
                python_lines.append(f"{indent}print({tac.arg1})")

        python_lines.append("\nif __name__ == '__main__':")
        python_lines.append("    main()")
        python_lines.append("    input('\\n[Execution Finished - Press Enter to Exit]')")

        return "\n".join(python_lines)